            uint[] outerValues = outer.Values;
            if (
                raised[FuzzyValue.Ins] > outerValues[FuzzyValue.MaxIns]
                || TotalErrors(raised) > outerValues[FuzzyValue.MaxErr]
            )
            {
                return false;
            }
        }

        return true;
    }

