                )
                {
                    state.NotePartialEvent(PartialEvent.InsertionRunOut);

                    return MatchStatus.Partial;
                }

                return MatchStatus.Failure;
            case FuzzyValue.Sub:
                // Could the character at text_pos have been substituted?
                if (step == 0)
                {
                    return MatchStatus.Failure;
                }

                newPos = Step(state, data.NewTextPos, step);

