        data.NewFoldedPos = foldedPos;
        data.FoldedLen = foldedLen;
        data.NewGfoldedPos = gfoldedPos;
        data.GfoldedLen = gfoldedLen;
        data.Step = step;
        data.FoldChangesStart = foldChangesStart;
