                    && SameCharIgn(node.Encoding, state.CharBefore(state.TextPos), node.Values[stringPos - 1])
                )
                {
                    if ((node.Status & NodeStatus.Fuzzy) != 0 && stringPos <= pattern.ExactDeletionCeiling)
                    {
